                i += 1
                continue
            j = i
            while j + 1 < len(active) and active[j + 1]:
                j += 1
            result.append((i, j))
            i = j + 1
        return result

    rb = blocks([any(v != 0 for v in row) for row in grid])
    cb = blocks([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    if not rb or not cb:
        return [row[:] for row in grid]

    ph = max(b - a + 1 for a, b in rb)
    pw = max(b - a + 1 for a, b in cb)

    # Interior colors distinguish the repeated background fill from the
    # colored marks that should be extended through the gaps.
    counts = Counter()
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1 + 1):
                if not 1 <= r - r0 < ph - 1:
                    continue
                for c in range(c0, c1 + 1):
                    if 1 <= c - c0 < pw - 1 and grid[r][c] != 0:
                        counts[grid[r][c]] += 1

    if not counts:
        return [row[:] for row in grid]
    background = counts.most_common(1)[0][0]
    marks = set(counts) - {background}
    out = [row[:] for row in grid]

    # Extend matching marks horizontally, filling only the blank separators.
    for r0, r1 in rb:
        for dy in range(1, ph - 1):
            r = r0 + dy
            if r > r1:
                continue
            for dx in range(1, pw - 1):
                by_color = {}
                for j, (c0, c1) in enumerate(cb):
                    c = c0 + dx
                    if c <= c1 and grid[r][c] in marks:
                        by_color.setdefault(grid[r][c], []).append(j)
                for color, ids in by_color.items():
                    for a, b in zip(ids, ids[1:]):
                        for j in range(a, b):
                            for c in range(cb[j][1] + 1, cb[j + 1][0]):
                                if out[r][c] == 0:
                                    out[r][c] = color

    # Extend matching marks vertically.
    for c0, c1 in cb:
        for dx in range(1, pw - 1):
            c = c0 + dx
            if c > c1:
                continue
            for dy in range(1, ph - 1):
                by_color = {}
                for i, (r0, r1) in enumerate(rb):
                    r = r0 + dy
                    if r <= r1 and grid[r][c] in marks:
                        by_color.setdefault(grid[r][c], []).append(i)
